class Example extends Phaser.Scene {
  create () {
    const player = this.add.rectangle(400, 300, 36, 36, 0x4488ff);
    const cursors = this.input.keyboard.createCursorKeys();
    this.events.on('update', () => {
      if (cursors.left.isDown)  player.x -= 2;
      if (cursors.right.isDown) player.x += 2;
      if (cursors.up.isDown)    player.y -= 2;
      if (cursors.down.isDown)  player.y += 2;
      player.x = Phaser.Math.Clamp(player.x, 18, 782);
      player.y = Phaser.Math.Clamp(player.y, 18, 582);
    });
  }
}
new Phaser.Game({ type: Phaser.AUTO, width: 800, height: 600, backgroundColor: '#1a1a2e', scene: Example });
